// Two-layer neural-net training demo.
//
// The target data is generated by a fixed 2-layer teacher network made of two
// 4×4 matrices with a tanh hidden activation and a tanh output activation:
//     y = tanh(W2ᵗ · tanh(W1ᵗ · x))
//
// Three students, all 2-layer with the same two activations, are trained with
// Adam on that data:
//   - dense4 : plain 4×4 · 4×4         (matches the teacher architecture)
//   - sparse : lifted 16×16 · 16×16, only a handful of cells per layer active,
//              positions random at init and moved by grow-and-prune, + L1
//   - dense16: lifted 16×16 · 16×16, every cell trainable (full capacity)
//
// The lifted models wrap the two trainable matrices in a fixed orthonormal
// up-projection U (16×4) and its transpose (down-projection), so all three see
// comparable 4-D data:  pred = tanh( Uᵀ · ( W2 · tanh( W1 · (U·x) ) ) ).

export type Matrix = number[][];
export type Vec = number[];

export const INPUT_DIM = 4;
export const OUTPUT_DIM = 4;
export const DATASET_SIZE = 64;
export const BATCH_SIZE = 8;
export const EPOCHS = 25;
export const LR = 0.04;
const BETA1 = 0.9;
const BETA2 = 0.999;
const ADAM_EPS = 1e-8;
const SEED = 17;
export const SPARSE_DIM = 16;
const SPARSE_ROUTING_SEED = 91;
const SPARSE_L1 = 0.05;
export const ACTIVE_COUNT = 36; // trainable cells per sparse layer (~2.25 nonzeros/row)

export type Mode = "dense4" | "sparse" | "dense16";

export interface LayerFrame {
  W: Matrix;
  grad: Matrix;
  m: Matrix;
  v: Matrix;
  active?: [number, number][]; // sparse layers only (dense = all cells)
  grown?: [number, number] | null;
  pruned?: [number, number] | null;
}

export interface Frame {
  step: number;
  epoch: number;
  batchInEpoch: number;
  batchIndices: number[];
  layers: LayerFrame[]; // [layer 1, layer 2]
  dataBatchLoss: number;
  dataFullLoss: number;
  l1Penalty: number;
  batchLoss: number;
  fullLoss: number;
  gradNorm: number;
}

export interface ModelCfg {
  dim: number; // 4 (plain) or 16 (lifted)
  lift: Matrix; // dim × 4
  unlift: Matrix; // 4 × dim
  unliftT: Matrix; // dim × 4  (= transpose(unlift))
  sparse: [boolean, boolean];
}

export interface Simulation {
  frames: Frame[];
  targets: Matrix;
  X: Matrix;
  cfg: ModelCfg;
}

export const MODE_META: Record<
  Mode,
  { badge: string; note: string; targetSub: string; batchSub: string }
> = {
  dense4: {
    badge: "Dense 4×4 · 4×4 — same architecture as the teacher",
    note: "pred = tanh(W₂ · tanh(W₁ · x)) with two trainable 4×4 matrices and the same two tanh activations as the network that generated the data. This is the matched-capacity reference: it should fit the data best.",
    targetSub: "Generated by the 2-layer teacher: y = tanh(W₂ᵗ · tanh(W₁ᵗ · x)).",
    batchSub: "Both 4×4 layers receive a gradient (full backprop through both tanh activations) and an Adam update every step.",
  },
  sparse: {
    badge: `Sparse 2-layer: ${ACTIVE_COUNT} movable cells per layer (grow-and-prune) + lift + L1`,
    note: `pred = tanh(Uᵀ · (W₂ · tanh(W₁ · U·x))). A fixed lift/unlift wraps two 16×16 layers; only ${ACTIVE_COUNT} cells per layer are trainable, random at init. Each epoch the largest-gradient cell of each layer is grown from zero and a near-zero, stable cell is pruned, keeping the count fixed. An L1 penalty pressures active weights toward zero.`,
    targetSub: "Same 2-layer teacher target as the other tabs.",
    batchSub: "Active cells in both layers drift via grow-and-prune; gradients backprop through both tanh activations, with an L1 term on the active weights.",
  },
  dense16: {
    badge: "Dense 2-layer: two full 16×16 layers + tanh + lift",
    note: "pred = tanh(Uᵀ · (W₂ · tanh(W₁ · U·x))) with the same fixed lift/unlift as the sparse tab, but every cell of both 16×16 layers is trainable (no sparsity, no grow-and-prune, no L1). The full-capacity upper bound for the lifted family.",
    targetSub: "Same 2-layer teacher target as the other tabs.",
    batchSub: "All cells of both 16×16 layers receive a gradient (backprop through both tanh activations) and an Adam update every step.",
  },
};

// ---------- rng / math helpers ----------

function mulberry32(a: number) {
  return function () {
    let t = (a += 0x6d2b79f5);
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function randn(rng: () => number): number {
  let u = 0,
    v = 0;
  while (u === 0) u = rng();
  while (v === 0) v = rng();
  return Math.sqrt(-2.0 * Math.log(u)) * Math.cos(2.0 * Math.PI * v);
}

function cloneMatrix(m: Matrix): Matrix {
  return m.map((row) => row.slice());
}

function matVec(M: Matrix, v: Vec): Vec {
  return M.map((row) => row.reduce((sum, w, i) => sum + w * v[i], 0));
}

function transposeMatrix(M: Matrix): Matrix {
  return M[0].map((_, j) => M.map((row) => row[j]));
}

function zeroMatrix(rows: number, cols = rows): Matrix {
  return Array.from({ length: rows }, () => Array(cols).fill(0));
}

function identity(n: number): Matrix {
  return Array.from({ length: n }, (_, i) => Array.from({ length: n }, (_, j) => (i === j ? 1 : 0)));
}

function mse(pred: Vec, target: Vec): number {
  let s = 0;
  for (let i = 0; i < pred.length; i++) {
    const d = pred[i] - target[i];
    s += d * d;
  }
  return s / pred.length;
}

export function maxAbs(arr: Vec): number {
  return Math.max(...arr.map((v) => Math.abs(v)), 1e-9);
}

export function flatten2D(m: Matrix): Vec {
  return m.flat();
}

export function msePublic(pred: Vec, target: Vec): number {
  return mse(pred, target);
}

const ACT = (v: number) => Math.tanh(v); // hidden and output activation (tanh)

function shuffleIndices(n: number, rng: () => number): number[] {
  const arr = Array.from({ length: n }, (_, i) => i);
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

function createEpochOrders(): number[][] {
  const rng = mulberry32(SEED + 101);
  const orders: number[][] = [];
  for (let epoch = 0; epoch < EPOCHS; epoch++) orders.push(shuffleIndices(DATASET_SIZE, rng));
  return orders;
}

// ---------- data: 2-layer teacher ----------

function buildDataset(rng: () => number) {
  const mat = (r: number, c: number, s: number): Matrix =>
    Array.from({ length: r }, () => Array.from({ length: c }, () => randn(rng) * s));
  const W1t = mat(INPUT_DIM, INPUT_DIM, 0.9);
  const W2t = mat(OUTPUT_DIM, INPUT_DIM, 0.9);
  const X = Array.from({ length: DATASET_SIZE }, () =>
    Array.from({ length: INPUT_DIM }, () => randn(rng) * 1.0)
  );
  const Y = X.map((x) => matVec(W2t, matVec(W1t, x).map(ACT)).map(ACT));
  return { X, Y };
}

// ---------- lift (orthonormal up-projection U, 16×4) ----------

function orthonormalizeColumns(matrix: Matrix): Matrix | null {
  const rows = matrix.length;
  const cols = matrix[0].length;
  const q = Array.from({ length: rows }, () => Array(cols).fill(0));
  for (let col = 0; col < cols; col++) {
    const v = matrix.map((row) => row[col]);
    for (let prev = 0; prev < col; prev++) {
      const qprev = q.map((row) => row[prev]);
      let proj = 0;
      for (let i = 0; i < rows; i++) proj += v[i] * qprev[i];
      for (let i = 0; i < rows; i++) v[i] -= proj * qprev[i];
    }
    let norm = 0;
    for (let i = 0; i < rows; i++) norm += v[i] * v[i];
    norm = Math.sqrt(norm);
    if (!isFinite(norm) || norm < 1e-12) return null;
    for (let i = 0; i < rows; i++) q[i][col] = v[i] / norm;
  }
  return q;
}

function buildLift(rng: () => number): Matrix {
  let up: Matrix | null = null;
  while (!up) {
    const raw = Array.from({ length: SPARSE_DIM }, () =>
      Array.from({ length: INPUT_DIM }, () => randn(rng))
    );
    up = orthonormalizeColumns(raw);
  }
  return up;
}

// ---------- forward / backward for the 2-layer model ----------

interface Forward {
  z: Vec;
  a1: Vec;
  h1: Vec;
  a2: Vec;
  u: Vec;
  pred: Vec;
}

export function forwardModel(W1: Matrix, W2: Matrix, x: Vec, cfg: ModelCfg): Forward {
  const z = matVec(cfg.lift, x); // lift (identity for dense4)
  const a1 = matVec(W1, z);
  const h1 = a1.map(ACT); // hidden activation
  const a2 = matVec(W2, h1);
  const u = matVec(cfg.unlift, a2); // unlift (identity for dense4)
  const pred = u.map(ACT); // output activation
  return { z, a1, h1, a2, u, pred };
}

// Dense gradients for both layers + mean data loss for a mini-batch.
function grads2(
  batchIndices: number[],
  X: Matrix,
  Y: Matrix,
  W1: Matrix,
  W2: Matrix,
  cfg: ModelCfg
): { gW1: Matrix; gW2: Matrix; dataLoss: number } {
  const dim = cfg.dim;
  const gW1 = zeroMatrix(dim);
  const gW2 = zeroMatrix(dim);
  let dataLoss = 0;
  const scale = 2 / (batchIndices.length * OUTPUT_DIM);
  const W2T = transposeMatrix(W2);
  for (const idx of batchIndices) {
    const { z, h1, pred } = forwardModel(W1, W2, X[idx], cfg);
    dataLoss += mse(pred, Y[idx]);
    // output: pred = tanh(u); ∂L/∂u = (pred − y) ⊙ (1 − pred²)
    const du = pred.map((p, i) => (p - Y[idx][i]) * (1 - p * p));
    const da2 = matVec(cfg.unliftT, du); // ∂L/∂a2  (dim)
    for (let i = 0; i < dim; i++) for (let j = 0; j < dim; j++) gW2[i][j] += scale * da2[i] * h1[j];
    const dh1 = matVec(W2T, da2); // ∂L/∂h1
    const da1 = dh1.map((d, i) => d * (1 - h1[i] * h1[i])); // through hidden tanh
    for (let i = 0; i < dim; i++) for (let j = 0; j < dim; j++) gW1[i][j] += scale * da1[i] * z[j];
  }
  return { gW1, gW2, dataLoss: dataLoss / batchIndices.length };
}

function fullLoss2(W1: Matrix, W2: Matrix, X: Matrix, Y: Matrix, cfg: ModelCfg): number {
  let total = 0;
  for (let n = 0; n < X.length; n++) total += mse(forwardModel(W1, W2, X[n], cfg).pred, Y[n]);
  return total / X.length;
}

// ---------- grow-and-prune (per sparse layer) ----------

function chooseGrow(grad: Matrix, activeSet: Set<string>, dim: number): [number, number] | null {
  let best: [number, number] | null = null;
  let bestScore = -1;
  for (let i = 0; i < dim; i++)
    for (let j = 0; j < dim; j++) {
      if (activeSet.has(`${i}:${j}`)) continue;
      const s = Math.abs(grad[i][j]);
      if (s > bestScore) {
        bestScore = s;
        best = [i, j];
      }
    }
  return best;
}

const PRUNE_W_FRAC = 0.35;
const PRUNE_M_FRAC = 0.4;
const PRUNE_G_FRAC = 0.6;

interface PruneChoice {
  pos: [number, number];
  wRatio: number;
  mRatio: number;
  gRatio: number;
}

function choosePrune(
  W: Matrix,
  m: Matrix,
  grad: Matrix,
  active: [number, number][]
): PruneChoice | null {
  let maxW = 1e-9;
  let maxM = 1e-9;
  let maxG = 1e-9;
  for (const [r, c] of active) {
    maxW = Math.max(maxW, Math.abs(W[r][c]));
    maxM = Math.max(maxM, Math.abs(m[r][c]));
    maxG = Math.max(maxG, Math.abs(grad[r][c]));
  }
  let best: PruneChoice | null = null;
  let bestScore = Infinity;
  for (const [r, c] of active) {
    const wRatio = Math.abs(W[r][c]) / maxW;
    const mRatio = Math.abs(m[r][c]) / maxM;
    const gRatio = Math.abs(grad[r][c]) / maxG;
    const dead = wRatio + mRatio + gRatio;
    if (dead < bestScore) {
      bestScore = dead;
      best = { pos: [r, c], wRatio, mRatio, gRatio };
    }
  }
  return best;
}

function isSafeToPrune(p: PruneChoice): boolean {
  return p.wRatio < PRUNE_W_FRAC && p.mRatio < PRUNE_M_FRAC && p.gRatio < PRUNE_G_FRAC;
}

function sparseL1Penalty(W: Matrix, active: [number, number][]): number {
  let sumAbs = 0;
  for (const [r, c] of active) sumAbs += Math.abs(W[r][c]);
  return SPARSE_L1 * (sumAbs / active.length);
}

// ---------- unified 2-layer trainer ----------

interface Layer {
  W: Matrix;
  m: Matrix;
  v: Matrix;
  sparse: boolean;
  activeSet: Set<string>;
  activeList: [number, number][];
}

function makeLayer(dim: number, sparse: boolean, W: Matrix): Layer {
  const activeList: [number, number][] = [];
  const activeSet = new Set<string>();
  for (let i = 0; i < dim; i++)
    for (let j = 0; j < dim; j++) {
      if (!sparse || Math.abs(W[i][j]) > 1e-12) {
        activeList.push([i, j]);
        activeSet.add(`${i}:${j}`);
      }
    }
  return { W: cloneMatrix(W), m: zeroMatrix(dim), v: zeroMatrix(dim), sparse, activeSet, activeList };
}

function applyGrowPrune(
  layer: Layer,
  grad: Matrix,
  dim: number
): { grown: [number, number] | null; pruned: [number, number] | null } {
  if (!layer.sparse) return { grown: null, pruned: null };
  const grow = chooseGrow(grad, layer.activeSet, dim);
  const prune = choosePrune(layer.W, layer.m, grad, layer.activeList);
  if (
    grow &&
    prune &&
    isSafeToPrune(prune) &&
    Math.abs(grad[grow[0]][grow[1]]) > Math.abs(grad[prune.pos[0]][prune.pos[1]])
  ) {
    const [gr, gc] = grow;
    const [pr, pc] = prune.pos;
    layer.activeSet.delete(`${pr}:${pc}`);
    layer.activeSet.add(`${gr}:${gc}`);
    layer.activeList = layer.activeList.filter(([a, b]) => !(a === pr && b === pc));
    layer.activeList.push([gr, gc]);
    layer.W[pr][pc] = 0;
    layer.m[pr][pc] = 0;
    layer.v[pr][pc] = 0;
    layer.W[gr][gc] = 0; // grow at zero: prediction unchanged at the swap
    layer.m[gr][gc] = 0;
    layer.v[gr][gc] = 0;
    return { grown: grow, pruned: prune.pos };
  }
  return { grown: null, pruned: null };
}

function buildTwoLayerFrames(
  X: Matrix,
  Y: Matrix,
  epochOrders: number[][],
  cfg: ModelCfg,
  init1: Matrix,
  init2: Matrix
): Frame[] {
  const dim = cfg.dim;
  const L1 = makeLayer(dim, cfg.sparse[0], init1);
  const L2 = makeLayer(dim, cfg.sparse[1], init2);
  const frames: Frame[] = [];
  let step = 0;

  const processLayer = (
    layer: Layer,
    gW: Matrix,
    adamStep: number,
    grown: [number, number] | null,
    pruned: [number, number] | null
  ): { frame: LayerFrame; gradSq: number } => {
    if (layer.sparse) {
      const s = SPARSE_L1 / layer.activeList.length;
      for (const [r, c] of layer.activeList) gW[r][c] += s * Math.sign(layer.W[r][c]);
    }
    const beta1Pow = Math.pow(BETA1, adamStep);
    const beta2Pow = Math.pow(BETA2, adamStep);
    const nextM = cloneMatrix(layer.m);
    const nextV = cloneMatrix(layer.v);
    let gradSq = 0;
    for (const [r, c] of layer.activeList) {
      const g = gW[r][c];
      nextM[r][c] = BETA1 * nextM[r][c] + (1 - BETA1) * g;
      nextV[r][c] = BETA2 * nextV[r][c] + (1 - BETA2) * g * g;
      gradSq += g * g;
    }
    const frame: LayerFrame = {
      W: cloneMatrix(layer.W),
      grad: cloneMatrix(gW),
      m: cloneMatrix(nextM),
      v: cloneMatrix(nextV),
      active: layer.sparse ? layer.activeList.map(([r, c]) => [r, c] as [number, number]) : undefined,
      grown,
      pruned,
    };
    for (const [r, c] of layer.activeList) {
      const mHat = nextM[r][c] / (1 - beta1Pow);
      const vHat = nextV[r][c] / (1 - beta2Pow);
      layer.W[r][c] -= (LR * mHat) / (Math.sqrt(vHat) + ADAM_EPS);
    }
    layer.m = nextM;
    layer.v = nextV;
    return { frame, gradSq };
  };

  for (let epoch = 0; epoch < EPOCHS; epoch++) {
    const order = epochOrders[epoch];
    for (let batchStart = 0; batchStart < DATASET_SIZE; batchStart += BATCH_SIZE) {
      const batchIndices = order.slice(batchStart, batchStart + BATCH_SIZE);

      let g1: { grown: [number, number] | null; pruned: [number, number] | null } = {
        grown: null,
        pruned: null,
      };
      let g2 = g1;
      if (epoch >= 1 && batchStart === 0) {
        const probe = grads2(batchIndices, X, Y, L1.W, L2.W, cfg);
        g1 = applyGrowPrune(L1, probe.gW1, dim);
        g2 = applyGrowPrune(L2, probe.gW2, dim);
      }

      const { gW1, gW2, dataLoss } = grads2(batchIndices, X, Y, L1.W, L2.W, cfg);
      const dataFullLoss = fullLoss2(L1.W, L2.W, X, Y, cfg);
      let l1Penalty = 0;
      if (L1.sparse) l1Penalty += sparseL1Penalty(L1.W, L1.activeList);
      if (L2.sparse) l1Penalty += sparseL1Penalty(L2.W, L2.activeList);

      const adamStep = step + 1;
      const r1 = processLayer(L1, gW1, adamStep, g1.grown, g1.pruned);
      const r2 = processLayer(L2, gW2, adamStep, g2.grown, g2.pruned);

      frames.push({
        step,
        epoch,
        batchInEpoch: batchStart / BATCH_SIZE,
        batchIndices,
        layers: [r1.frame, r2.frame],
        dataBatchLoss: dataLoss,
        dataFullLoss,
        l1Penalty,
        batchLoss: dataLoss + l1Penalty,
        fullLoss: dataFullLoss + l1Penalty,
        gradNorm: Math.sqrt(r1.gradSq + r2.gradSq),
      });
      step += 1;
    }
  }
  return frames;
}

// ---------- random initialisers ----------

function randomDense(rng: () => number, dim: number, scale: number): Matrix {
  return Array.from({ length: dim }, () =>
    Array.from({ length: dim }, () => randn(rng) * scale)
  );
}

function randomSparse(rng: () => number, dim: number, count: number, scale: number): Matrix {
  const W = zeroMatrix(dim);
  const used = new Set<string>();
  let placed = 0;
  while (placed < count) {
    const r = Math.floor(rng() * dim);
    const c = Math.floor(rng() * dim);
    const key = `${r}:${c}`;
    if (used.has(key)) continue;
    used.add(key);
    W[r][c] = randn(rng) * scale;
    placed += 1;
  }
  return W;
}

// Build all three simulations once. Deterministic (seeded).
export function buildSimulations(): Record<Mode, Simulation> {
  const dataset = buildDataset(mulberry32(SEED));
  const { X, Y } = dataset;
  const epochOrders = createEpochOrders();

  const I4 = identity(INPUT_DIM);
  const U = buildLift(mulberry32(SEED + SPARSE_ROUTING_SEED)); // 16×4
  const UT = transposeMatrix(U); // 4×16 (down-projection)

  const dense4Cfg: ModelCfg = { dim: 4, lift: I4, unlift: I4, unliftT: I4, sparse: [false, false] };
  const liftedCfg = (sparse: [boolean, boolean]): ModelCfg => ({
    dim: SPARSE_DIM,
    lift: U,
    unlift: UT,
    unliftT: transposeMatrix(UT), // = U (16×4)
    sparse,
  });

  const d4 = mulberry32(SEED + 11);
  const sp = mulberry32(SEED + 22);
  const d16 = mulberry32(SEED + 33);

  return {
    dense4: {
      frames: buildTwoLayerFrames(
        X,
        Y,
        epochOrders,
        dense4Cfg,
        randomDense(d4, 4, 0.7),
        randomDense(d4, 4, 0.7)
      ),
      targets: Y,
      X,
      cfg: dense4Cfg,
    },
    sparse: {
      frames: buildTwoLayerFrames(
        X,
        Y,
        epochOrders,
        liftedCfg([true, true]),
        randomSparse(sp, SPARSE_DIM, ACTIVE_COUNT, 0.6),
        randomSparse(sp, SPARSE_DIM, ACTIVE_COUNT, 0.6)
      ),
      targets: Y,
      X,
      cfg: liftedCfg([true, true]),
    },
    dense16: {
      frames: buildTwoLayerFrames(
        X,
        Y,
        epochOrders,
        liftedCfg([false, false]),
        randomDense(d16, SPARSE_DIM, 0.35),
        randomDense(d16, SPARSE_DIM, 0.35)
      ),
      targets: Y,
      X,
      cfg: liftedCfg([false, false]),
    },
  };
}
